import{_ as t}from"./chunks/group.B0Ah2Z4E.js";import{_ as a,c as o,o as i,ag as n}from"./chunks/framework.bCALENAD.js";const g=JSON.parse('{"title":"About Us","description":"","frontmatter":{"outline":"deep","title":"About Us"},"headers":[],"relativePath":"en/overview/about.md","filePath":"en/overview/about.md","lastUpdated":1769840252000}'),r={name:"en/overview/about.md"};function s(l,e,u,d,h,p){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="about-us" tabindex="-1">About Us <a class="header-anchor" href="#about-us" aria-label="Permalink to &quot;About Us&quot;">​</a></h1><h2 id="📞contact-information" tabindex="-1">📞Contact Information <a class="header-anchor" href="#📞contact-information" aria-label="Permalink to &quot;📞Contact Information&quot;">​</a></h2><p>If you have any questions or suggestions about the project, please contact us through the following ways:</p><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><ul><li><strong>Main Project</strong>: <a href="https://github.com/fastapiadmin/FastapiAdmin" target="_blank" rel="noreferrer">fastapiadmin/FastapiAdmin</a></li><li><strong>Mobile Application</strong>: <a href="https://github.com/fastapiadmin/FastApp" target="_blank" rel="noreferrer">fastapiadmin/FastApp</a></li><li><strong>Official Documentation</strong>: <a href="https://github.com/fastapiadmin/FastDocs" target="_blank" rel="noreferrer">fastapiadmin/FastDocs</a></li></ul><h3 id="gitee" tabindex="-1">Gitee <a class="header-anchor" href="#gitee" aria-label="Permalink to &quot;Gitee&quot;">​</a></h3><ul><li><strong>Main Project</strong>: <a href="https://gitee.com/fastapiadmin/FastapiAdmin" target="_blank" rel="noreferrer">fastapiadmin/FastapiAdmin</a></li></ul><h3 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h3><ul><li><strong>Technical Support</strong>: <a href="mailto:948080782@qq.com" target="_blank" rel="noreferrer">948080782@qq.com</a></li></ul><h3 id="wechat" tabindex="-1">WeChat <a class="header-anchor" href="#wechat" aria-label="Permalink to &quot;WeChat&quot;">​</a></h3><ul><li><p><strong>Official Account</strong>: FastApiAdmin</p></li><li><p><strong>Technical Exchange Group</strong>: Please scan the QR code below to join</p><p><img src="'+t+'" alt="WeChat Group"></p></li></ul><h2 id="🤝contribution-guide" tabindex="-1">🤝Contribution Guide <a class="header-anchor" href="#🤝contribution-guide" aria-label="Permalink to &quot;🤝Contribution Guide&quot;">​</a></h2><p>We welcome community contributions, including but not limited to:</p><h3 id="how-to-contribute" tabindex="-1">How to Contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to &quot;How to Contribute&quot;">​</a></h3><ol><li><strong>Star and Fork</strong> the repository on GitHub</li><li><strong>Clone</strong> the forked repository to your local machine</li><li><strong>Create</strong> a new branch for your feature or bug fix</li><li><strong>Make</strong> the necessary changes and commit them</li><li><strong>Push</strong> your changes to your forked repository</li><li><strong>Create</strong> a Pull Request to the main repository</li></ol><h3 id="contribution-guidelines" tabindex="-1">Contribution Guidelines <a class="header-anchor" href="#contribution-guidelines" aria-label="Permalink to &quot;Contribution Guidelines&quot;">​</a></h3><ul><li><strong>Code Quality</strong>: Follow the project&#39;s coding standards and style guidelines</li><li><strong>Documentation</strong>: Update documentation for any changes you make</li><li><strong>Testing</strong>: Add tests for new features and ensure existing tests pass</li><li><strong>Commit Messages</strong>: Use clear and descriptive commit messages</li><li><strong>Pull Requests</strong>: Provide a clear description of the changes and why they are needed</li></ul><h3 id="areas-for-contribution" tabindex="-1">Areas for Contribution <a class="header-anchor" href="#areas-for-contribution" aria-label="Permalink to &quot;Areas for Contribution&quot;">​</a></h3><ul><li><strong>Bug Fixes</strong>: Fix issues reported in the GitHub Issues</li><li><strong>Feature Development</strong>: Implement new features requested by the community</li><li><strong>Documentation</strong>: Improve existing documentation or add new documentation</li><li><strong>Code Optimization</strong>: Optimize existing code for better performance</li><li><strong>UI/UX Improvement</strong>: Enhance the user interface and user experience</li><li><strong>Translation</strong>: Translate documentation into different languages</li></ul><h2 id="📄license" tabindex="-1">📄License <a class="header-anchor" href="#📄license" aria-label="Permalink to &quot;📄License&quot;">​</a></h2><p>This project adopts the <strong>MIT License</strong>, which is a permissive open source license that allows for free use, modification, and distribution of the software.</p><h3 id="mit-license-summary" tabindex="-1">MIT License Summary <a class="header-anchor" href="#mit-license-summary" aria-label="Permalink to &quot;MIT License Summary&quot;">​</a></h3><ul><li><strong>Free to use</strong>: You can use the software for any purpose</li><li><strong>Free to modify</strong>: You can modify the software as needed</li><li><strong>Free to distribute</strong>: You can distribute the original or modified software</li><li><strong>Attribution required</strong>: You must include the original license and copyright notice</li><li><strong>No warranty</strong>: The software is provided &quot;as is&quot; without warranty</li></ul><h3 id="full-license-text" tabindex="-1">Full License Text <a class="header-anchor" href="#full-license-text" aria-label="Permalink to &quot;Full License Text&quot;">​</a></h3><p>For the full license text, please refer to the <a href="https://github.com/fastapiadmin/FastapiAdmin/blob/master/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> file in the repository.</p><h2 id="🌟acknowledgements" tabindex="-1">🌟Acknowledgements <a class="header-anchor" href="#🌟acknowledgements" aria-label="Permalink to &quot;🌟Acknowledgements&quot;">​</a></h2><p>We would like to express our gratitude to the following open source projects and communities that have contributed to the development of FastapiAdmin:</p><h3 id="core-dependencies" tabindex="-1">Core Dependencies <a class="header-anchor" href="#core-dependencies" aria-label="Permalink to &quot;Core Dependencies&quot;">​</a></h3><ul><li><strong>FastAPI</strong>: Modern, fast (high-performance), web framework for building APIs with Python 3.7+</li><li><strong>Vue.js</strong>: Progressive JavaScript framework for building user interfaces</li><li><strong>TypeScript</strong>: Typed superset of JavaScript that compiles to plain JavaScript</li><li><strong>ElementPlus</strong>: A Vue 3 based component library for designers and developers</li><li><strong>Uni App</strong>: Cross-platform application framework based on Vue.js</li><li><strong>SQLAlchemy</strong>: The Python SQL toolkit and Object Relational Mapper</li><li><strong>Redis</strong>: In-memory data structure store, used as a database, cache, and message broker</li><li><strong>MySQL</strong>: Relational database management system</li><li><strong>Docker</strong>: Open platform for developing, shipping, and running applications</li></ul><h3 id="development-tools" tabindex="-1">Development Tools <a class="header-anchor" href="#development-tools" aria-label="Permalink to &quot;Development Tools&quot;">​</a></h3><ul><li><strong>Vite</strong>: Next generation frontend tooling</li><li><strong>Pnpm</strong>: Fast, disk space efficient package manager</li><li><strong>ESLint</strong>: Pluggable JavaScript linter</li><li><strong>Prettier</strong>: Opinionated code formatter</li><li><strong>Black</strong>: Uncompromising Python code formatter</li><li><strong>Mypy</strong>: Optional static typing for Python</li></ul><h3 id="community-support" tabindex="-1">Community Support <a class="header-anchor" href="#community-support" aria-label="Permalink to &quot;Community Support&quot;">​</a></h3><ul><li><strong>GitHub</strong>: Platform for version control and collaboration</li><li><strong>Gitee</strong>: Domestic code hosting platform for Chinese developers</li><li><strong>Stack Overflow</strong>: Question and answer site for professional and enthusiast programmers</li><li><strong>Reddit</strong>: Community for discussing programming and technology</li><li><strong>WeChat Groups</strong>: Domestic technical exchange communities</li></ul><h2 id="🚀project-status" tabindex="-1">🚀Project Status <a class="header-anchor" href="#🚀project-status" aria-label="Permalink to &quot;🚀Project Status&quot;">​</a></h2><h3 id="current-version" tabindex="-1">Current Version <a class="header-anchor" href="#current-version" aria-label="Permalink to &quot;Current Version&quot;">​</a></h3><ul><li><strong>Main Project</strong>: V2.0.0</li><li><strong>Mobile Application</strong>: V1.0.0</li><li><strong>Documentation</strong>: V1.0.0</li></ul><h3 id="development-roadmap" tabindex="-1">Development Roadmap <a class="header-anchor" href="#development-roadmap" aria-label="Permalink to &quot;Development Roadmap&quot;">​</a></h3><h4 id="short-term-goals-1-3-months" tabindex="-1">Short-term Goals (1-3 months) <a class="header-anchor" href="#short-term-goals-1-3-months" aria-label="Permalink to &quot;Short-term Goals (1-3 months)&quot;">​</a></h4><ul><li><strong>Bug Fixes</strong>: Resolve any reported issues</li><li><strong>Performance Optimization</strong>: Improve system performance and response speed</li><li><strong>Documentation Enhancement</strong>: Complete and improve documentation</li><li><strong>Mobile Application</strong>: Add more features to the mobile app</li></ul><h4 id="medium-term-goals-3-6-months" tabindex="-1">Medium-term Goals (3-6 months) <a class="header-anchor" href="#medium-term-goals-3-6-months" aria-label="Permalink to &quot;Medium-term Goals (3-6 months)&quot;">​</a></h4><ul><li><strong>AI Integration</strong>: Integrate AI capabilities into the development process</li><li><strong>Microservices Support</strong>: Add support for microservices architecture</li><li><strong>Low-code Platform</strong>: Develop a low-code platform for faster application development</li><li><strong>More Templates</strong>: Create industry-specific templates</li></ul><h4 id="long-term-goals-6-12-months" tabindex="-1">Long-term Goals (6-12 months) <a class="header-anchor" href="#long-term-goals-6-12-months" aria-label="Permalink to &quot;Long-term Goals (6-12 months)&quot;">​</a></h4><ul><li><strong>Enterprise-level Features</strong>: Add more enterprise-level features</li><li><strong>Internationalization</strong>: Better support for multi-language and multi-region</li><li><strong>Ecosystem Expansion</strong>: Build a complete ecosystem around FastapiAdmin</li><li><strong>Community Growth</strong>: Grow the community and attract more contributors</li></ul><h2 id="💡faq" tabindex="-1">💡FAQ <a class="header-anchor" href="#💡faq" aria-label="Permalink to &quot;💡FAQ&quot;">​</a></h2><h3 id="general-questions" tabindex="-1">General Questions <a class="header-anchor" href="#general-questions" aria-label="Permalink to &quot;General Questions&quot;">​</a></h3><h4 id="q-what-is-fastapiadmin" tabindex="-1">Q: What is FastapiAdmin? <a class="header-anchor" href="#q-what-is-fastapiadmin" aria-label="Permalink to &quot;Q: What is FastapiAdmin?&quot;">​</a></h4><p>A: FastapiAdmin is a modern, open-source, full-stack rapid development platform based on FastAPI, Vue3, and Uni App. It is designed to help developers efficiently build high-quality enterprise-level backend systems.</p><h4 id="q-is-fastapiadmin-free-to-use" tabindex="-1">Q: Is FastapiAdmin free to use? <a class="header-anchor" href="#q-is-fastapiadmin-free-to-use" aria-label="Permalink to &quot;Q: Is FastapiAdmin free to use?&quot;">​</a></h4><p>A: Yes, FastapiAdmin is completely open source under the MIT License, which allows for free use, modification, and distribution.</p><h4 id="q-what-programming-languages-are-used-in-fastapiadmin" tabindex="-1">Q: What programming languages are used in FastapiAdmin? <a class="header-anchor" href="#q-what-programming-languages-are-used-in-fastapiadmin" aria-label="Permalink to &quot;Q: What programming languages are used in FastapiAdmin?&quot;">​</a></h4><p>A: Backend: Python; Frontend: JavaScript/TypeScript; Mobile: JavaScript/TypeScript</p><h4 id="q-does-fastapiadmin-support-mobile-development" tabindex="-1">Q: Does FastapiAdmin support mobile development? <a class="header-anchor" href="#q-does-fastapiadmin-support-mobile-development" aria-label="Permalink to &quot;Q: Does FastapiAdmin support mobile development?&quot;">​</a></h4><p>A: Yes, FastapiAdmin includes a mobile application called FastApp, which is based on Uni App and supports multiple platforms including WeChat Mini Program, H5, iOS, and Android.</p><h3 id="technical-questions" tabindex="-1">Technical Questions <a class="header-anchor" href="#technical-questions" aria-label="Permalink to &quot;Technical Questions&quot;">​</a></h3><h4 id="q-what-database-does-fastapiadmin-use" tabindex="-1">Q: What database does FastapiAdmin use? <a class="header-anchor" href="#q-what-database-does-fastapiadmin-use" aria-label="Permalink to &quot;Q: What database does FastapiAdmin use?&quot;">​</a></h4><p>A: FastapiAdmin supports MySQL and MongoDB. MySQL is used by default, but you can configure it to use MongoDB if needed.</p><h4 id="q-does-fastapiadmin-support-docker-deployment" tabindex="-1">Q: Does FastapiAdmin support Docker deployment? <a class="header-anchor" href="#q-does-fastapiadmin-support-docker-deployment" aria-label="Permalink to &quot;Q: Does FastapiAdmin support Docker deployment?&quot;">​</a></h4><p>A: Yes, FastapiAdmin provides complete Docker deployment support, including Docker Compose configuration and Nginx reverse proxy setup.</p><h4 id="q-what-authentication-mechanism-does-fastapiadmin-use" tabindex="-1">Q: What authentication mechanism does FastapiAdmin use? <a class="header-anchor" href="#q-what-authentication-mechanism-does-fastapiadmin-use" aria-label="Permalink to &quot;Q: What authentication mechanism does FastapiAdmin use?&quot;">​</a></h4><p>A: FastapiAdmin uses JWT OAuth2 authentication mechanism, which is secure, reliable, and easy to scale.</p><h4 id="q-can-fastapiadmin-handle-high-concurrency" tabindex="-1">Q: Can FastapiAdmin handle high concurrency? <a class="header-anchor" href="#q-can-fastapiadmin-handle-high-concurrency" aria-label="Permalink to &quot;Q: Can FastapiAdmin handle high concurrency?&quot;">​</a></h4><p>A: Yes, FastapiAdmin is based on the FastAPI asynchronous framework, which handles concurrent requests efficiently. It also supports load balancing and horizontal scaling.</p><h3 id="deployment-questions" tabindex="-1">Deployment Questions <a class="header-anchor" href="#deployment-questions" aria-label="Permalink to &quot;Deployment Questions&quot;">​</a></h3><h4 id="q-how-to-deploy-fastapiadmin" tabindex="-1">Q: How to deploy FastapiAdmin? <a class="header-anchor" href="#q-how-to-deploy-fastapiadmin" aria-label="Permalink to &quot;Q: How to deploy FastapiAdmin?&quot;">​</a></h4><p>A: FastapiAdmin supports multiple deployment methods:</p><ul><li>Docker Compose deployment (recommended)</li><li>Manual deployment</li><li>Cloud service deployment</li></ul><p>Detailed deployment steps can be found in the <a href="/en/quickstart/deployment">Deployment Guide</a>.</p><h4 id="q-what-are-the-server-requirements-for-fastapiadmin" tabindex="-1">Q: What are the server requirements for FastapiAdmin? <a class="header-anchor" href="#q-what-are-the-server-requirements-for-fastapiadmin" aria-label="Permalink to &quot;Q: What are the server requirements for FastapiAdmin?&quot;">​</a></h4><p>A: Minimum requirements:</p><ul><li>CPU: 2 cores</li><li>Memory: 4GB</li><li>Disk: 50GB</li><li>Network: 100Mbps</li><li>OS: Linux (Ubuntu 20.04+ recommended)</li></ul><p>Recommended requirements for production environment:</p><ul><li>CPU: 4 cores+</li><li>Memory: 8GB+</li><li>Disk: 100GB+</li><li>Network: 1Gbps+</li></ul><h3 id="support-questions" tabindex="-1">Support Questions <a class="header-anchor" href="#support-questions" aria-label="Permalink to &quot;Support Questions&quot;">​</a></h3><h4 id="q-how-to-get-technical-support" tabindex="-1">Q: How to get technical support? <a class="header-anchor" href="#q-how-to-get-technical-support" aria-label="Permalink to &quot;Q: How to get technical support?&quot;">​</a></h4><p>A: You can get technical support through:</p><ul><li>GitHub Issues: For bug reports and feature requests</li><li>Email: <a href="mailto:948080782@qq.com" target="_blank" rel="noreferrer">948080782@qq.com</a></li><li>WeChat Group: For real-time technical exchange</li></ul><h4 id="q-how-to-report-a-bug" tabindex="-1">Q: How to report a bug? <a class="header-anchor" href="#q-how-to-report-a-bug" aria-label="Permalink to &quot;Q: How to report a bug?&quot;">​</a></h4><p>A: Please report bugs on the GitHub Issues page with the following information:</p><ul><li>Bug description</li><li>Steps to reproduce</li><li>Expected behavior</li><li>Actual behavior</li><li>Environment information (Python version, FastAPI version, etc.)</li><li>Screenshots (if applicable)</li></ul><h4 id="q-how-to-request-a-new-feature" tabindex="-1">Q: How to request a new feature? <a class="header-anchor" href="#q-how-to-request-a-new-feature" aria-label="Permalink to &quot;Q: How to request a new feature?&quot;">​</a></h4><p>A: You can request new features on the GitHub Issues page with the following information:</p><ul><li>Feature description</li><li>Use case</li><li>Expected functionality</li><li>Any relevant screenshots or examples</li></ul><h2 id="📞contact-us" tabindex="-1">📞Contact Us <a class="header-anchor" href="#📞contact-us" aria-label="Permalink to &quot;📞Contact Us&quot;">​</a></h2><p>If you have any questions, suggestions, or would like to contribute to the project, please feel free to contact us through the following channels:</p><ul><li><p><strong>GitHub</strong>: <a href="https://github.com/fastapiadmin/FastapiAdmin" target="_blank" rel="noreferrer">fastapiadmin/FastapiAdmin</a></p></li><li><p><strong>Email</strong>: <a href="mailto:948080782@qq.com" target="_blank" rel="noreferrer">948080782@qq.com</a></p></li><li><p><strong>WeChat</strong>: Scan the QR code to join the technical exchange group</p><p><img src="'+t+'" alt="WeChat Group"></p></li></ul><p>We look forward to your feedback and contributions!</p><h2 id="🎉conclusion" tabindex="-1">🎉Conclusion <a class="header-anchor" href="#🎉conclusion" aria-label="Permalink to &quot;🎉Conclusion&quot;">​</a></h2><p><strong>FastapiAdmin</strong> is more than just a development platform—it&#39;s a community-driven project that aims to simplify and accelerate the development of enterprise-level applications.</p><p>With its advanced technology stack, complete functional modules, and excellent performance, FastapiAdmin provides a solid foundation for building modern, scalable, and maintainable applications.</p><p>We invite you to join our community, contribute to the project, and help us make FastapiAdmin even better!</p><p>Thank you for choosing FastapiAdmin!</p>',91)])])}const f=a(r,[["render",s]]);export{g as __pageData,f as default};
